"use strict";
const QUIZ = {"rank":1,"slug":"life-rhythm","theme":"morning","atlas":"everyday","tile":0,"title":"你适合什么样的生活节奏","setting":"把日子放回自己的时区","category":"生活节奏","intro":"有的人把早晨过成一壶慢水，有的人等城市熄灯才真正醒来。想想你舒服的那几天，看看它们有什么共同点。","dimensions":["规律","留白","冲刺","相聚"],"sections":["醒来以后","一天的正中间","生活有变","下班以后","理想的一周"],"resultTitle":"你的生活时区","action":"找我的节奏","details":["你为什么舒服在这里","给下周的一个小实验","你的生活彩蛋"],"profiles":[{"name":"晨线时区","identity":"规律先行","quote":"天亮之前，先留一小段时间给自己。","reason":"你容易被稳定的起点照顾到。把头两件事安排好，剩下的变化也就有地方安放。","strength":"挑一个固定的开机动作。倒杯水、拉开帘子或者写下一件今天要做的事，连续试五天。","extra":"你的日历上可能有一条重复提醒叫「给花浇水」，比人还准时。"},{"name":"空窗时区","identity":"留白优先","quote":"你的好日子里，一定有一格谁也约不到。","reason":"你需要没被预订的时间，才知道自己累不累、想不想。空下来以后，你对周围也更有耐心。","strength":"在下周先锁一晚空白。到了那个晚上才决定读书、闲走，或提早睡觉。","extra":"别人问晚上去哪儿，你的计划是再看十分钟窗外。"},{"name":"潮汐时区","identity":"集中发力","quote":"你有自己的涨潮，别拿整天去等那一小时。","reason":"任务真有趣时，你进入状态很快，也乐意一口气做深。持续的小打断反倒把精力切得最碎。","strength":"找出最有精神的九十分钟，只开一项任务。结束后留十五分钟真的离开桌子。","extra":"开始整理一张照片，回过神已经给十年前的文件都起了名字。"},{"name":"灯火时区","identity":"以相聚充电","quote":"有人说「慢慢来」，你听见的是「忙完一起吃」。","reason":"你从人的回应里得到能量。有人一起吃饭、做事或聊两句，普通一天也有了收尾的理由。","strength":"约一个不用盛装出席的小见面。散完步各自回家，让相聚保留一点余味。","extra":"手机最常出现的一句可能是「我也正好在附近」。"},{"name":"小岛时区","identity":"规律与留白","quote":"把锚放好，岛上就可以慢慢逛。","reason":"你喜欢一天有几个固定落点，中间可以自己走。这让你同时享受秩序和余裕。","strength":"只固定起床后和睡前的一个动作。两点之间空一小段，用当时的心情决定。","extra":"连安排什么都不做，你也可能先给它挑个合适的时段。"},{"name":"云涌时区","identity":"独处与爆发","quote":"安静里攒的劲，会在你真的喜欢时冒出来。","reason":"你先让自己慢慢热起来，投入后却很少敷衍。给你空间，就是帮你进入状态。","strength":"把一段完整的独处交给一个想了几天的念头，再给收尾留十分钟。","extra":"你说「我先放空一会儿」，多半是晚一点有东西要端出来。"},{"name":"夜航时区","identity":"行动与同伴","quote":"你喜欢干完活之后，灯还亮着，朋友也还在。","reason":"好伙伴能让你快速开工，专注的进展又让你更愿意分享。你喜欢有热气的行动。","strength":"试试和一位朋友共做六十分钟，各忙各的。结束喝一杯东西，互相说说推进了什么。","extra":"你最懂那种点了宵夜才想起原来已经十一点的心情。"},{"name":"周末站台","identity":"相聚与锚点","quote":"生活有个总站，朋友也知道几点能碰见你。","reason":"你享受熟悉关系，也珍惜生活有顺序。固定的见面会比临时起意陪你走更久。","strength":"把一顿饭或一次散步定成隔周见面的约定，留点弹性给临时来的人。","extra":"有一条路你走过很多遍，每次一边走一边把这一周说完。"}],"questions":[{"prompt":"闹钟还没响，你比预定时间早醒了半小时。","options":[{"dimension":0,"text":"按往常顺序洗漱做早餐"},{"dimension":1,"text":"继续躺着听窗外"},{"dimension":2,"text":"趁清醒先推进一件大事"},{"dimension":3,"text":"看看谁醒着发个早安"}]},{"prompt":"早餐有人顺手送到门口，你现在会怎么安排？","options":[{"dimension":1,"text":"倚在窗边一点点吃完"},{"dimension":2,"text":"迅速吃完把这一上午空给正事"},{"dimension":3,"text":"叫室友出来尝一口"},{"dimension":0,"text":"收起来，到常吃早餐的点再吃"}]},{"prompt":"你在家工作时最喜欢听到什么声音？","options":[{"dimension":2,"text":"歌单里能让我沉下来的节拍"},{"dimension":3,"text":"同住的人偶尔说句话"},{"dimension":0,"text":"计时器规律地提醒休息"},{"dimension":1,"text":"风和偶尔经过的车"}]},{"prompt":"上午有三件小事要做，时间挺充裕。","options":[{"dimension":3,"text":"边做边和同伴对进度"},{"dimension":0,"text":"写个顺序一步步来"},{"dimension":1,"text":"挑一件看得顺眼的先做"},{"dimension":2,"text":"集中半小时一次清完"}]},{"prompt":"早上出门发现天气比预报舒服很多。","options":[{"dimension":1,"text":"多走两条街再转回原路"},{"dimension":0,"text":"照平常走，记下下次去公园的时间"},{"dimension":3,"text":"问附近的朋友一起喝杯东西"},{"dimension":2,"text":"快点出门，顺便跑一个来回"}]},{"prompt":"快要迟到了，门口还有一个东西没找到。","options":[{"dimension":2,"text":"给自己九十秒翻三个地方"},{"dimension":1,"text":"先深呼吸，决定它值不值得找"},{"dimension":0,"text":"按常放东西的位置依次找"},{"dimension":3,"text":"请身边人一边听我说一边帮忙找"}]},{"prompt":"周日早晨最让你觉得踏实的是哪一幕？","options":[{"dimension":3,"text":"和熟悉的人坐到同一桌"},{"dimension":2,"text":"忽然想到一个想马上动手的点子"},{"dimension":1,"text":"没有消息催我起床"},{"dimension":0,"text":"按平常起床时间煮好饭"}]},{"prompt":"进入一个全新的作息，你靠什么适应？","options":[{"dimension":0,"text":"先找到固定起床和吃饭的点"},{"dimension":3,"text":"和同样适应的人聊聊各自的方法"},{"dimension":2,"text":"把最难熬的那两天集中安排过去"},{"dimension":1,"text":"给自己几天边过边调整"}]},{"prompt":"午饭多出四十分钟空当。","options":[{"dimension":2,"text":"解决一件下午最怕开头的任务"},{"dimension":3,"text":"去找认识的人拼个桌"},{"dimension":0,"text":"按常用路线散一圈再回来"},{"dimension":1,"text":"靠着椅背眯一会儿"}]},{"prompt":"你最愿意把下列哪一项设成「免打扰」？","options":[{"dimension":3,"text":"和亲近人面对面聊天的那阵子"},{"dimension":0,"text":"每天重复的固定习惯"},{"dimension":1,"text":"任何一段好不容易空出来的时间"},{"dimension":2,"text":"脑子最投入的那一个半小时"}]},{"prompt":"多人在线开会超了半小时。","options":[{"dimension":0,"text":"按原定清单挪动后续时间"},{"dimension":1,"text":"先喝水走一走再看接下来"},{"dimension":2,"text":"把剩余关键事项并到一个时段"},{"dimension":3,"text":"约有空的人会后把分歧说清"}]},{"prompt":"朋友忽然取消两人约好的午餐。","options":[{"dimension":1,"text":"随便走到一家有空位的店"},{"dimension":2,"text":"把这段空当用来集中做件事"},{"dimension":3,"text":"看还有没有朋友能一起吃"},{"dimension":0,"text":"把备用便当拿出来按时吃"}]},{"prompt":"一天里你什么时候最有「事情走上正轨了」的感觉？","options":[{"dimension":3,"text":"有人和我互道一声「搞定了」"},{"dimension":2,"text":"任务进入快而深的阶段"},{"dimension":1,"text":"我听见周围安静下来的时候"},{"dimension":0,"text":"第一项可重复的小事结束后"}]},{"prompt":"总也写不好的消息，在草稿里躺了三天。","options":[{"dimension":0,"text":"固定一个时间坐下来写"},{"dimension":3,"text":"找熟人念一遍听听语气"},{"dimension":2,"text":"限时十分钟一次写完发出"},{"dimension":1,"text":"先离开屏幕，想清楚再写"}]},{"prompt":"夏天午后犯困，你的常见做法是？","options":[{"dimension":1,"text":"困多久休息多久"},{"dimension":0,"text":"按惯例短睡十五分钟"},{"dimension":3,"text":"下楼和朋友一起买杯喝的"},{"dimension":2,"text":"先再推进最后一个段落"}]},{"prompt":"四个下午里，有一个可以自行安排。","options":[{"dimension":2,"text":"挑精神最好的，用来解决大项目"},{"dimension":1,"text":"先不填，到了那天再感受"},{"dimension":0,"text":"选同一天同一时间，方便以后照做"},{"dimension":3,"text":"选最容易和人碰头的那个"}]},{"prompt":"排好的行程临时全部打乱，你先保住什么？","options":[{"dimension":0,"text":"早餐、午餐或睡觉的基本时点"},{"dimension":1,"text":"一段自己的安静"},{"dimension":2,"text":"最能推进的那一个项目"},{"dimension":3,"text":"跟人约好的时间"}]},{"prompt":"连续几天没睡好，打算先改哪里？","options":[{"dimension":1,"text":"给晚上的最后一小时松绑"},{"dimension":2,"text":"把容易熬夜的任务集中到白天"},{"dimension":3,"text":"请朋友陪我吃顿早一点的晚饭"},{"dimension":0,"text":"先恢复固定的起床时间"}]},{"prompt":"月底事情突然堆在一起，谁的建议最容易听进去？","options":[{"dimension":2,"text":"找最关键的一块，做出明显进展"},{"dimension":3,"text":"叫两个伙伴先把担子分开"},{"dimension":0,"text":"分到每天，照常起落"},{"dimension":1,"text":"临时给自己腾出喘气的空间"}]},{"prompt":"你怎么知道这周该少接一个约？","options":[{"dimension":3,"text":"每次见面前我都觉得在赶场"},{"dimension":0,"text":"已经挤掉了两次原有习惯"},{"dimension":1,"text":"一想到有空就想把手机关掉"},{"dimension":2,"text":"怎么都找不到一整块能投入的时间"}]},{"prompt":"一项做熟了的事突然换成别的方法。","options":[{"dimension":1,"text":"慢慢试几次，允许手不熟"},{"dimension":0,"text":"先写一张可照着走的新流程"},{"dimension":3,"text":"找也在学的人一起练几遍"},{"dimension":2,"text":"集中摸索出一个能用的版本"}]},{"prompt":"回老家住几天，生活步调和独处时间都变了。","options":[{"dimension":2,"text":"腾一个下午把想做的事一口气做掉"},{"dimension":1,"text":"找个能一个人待会儿的角落"},{"dimension":0,"text":"先固定散步和睡觉的时间"},{"dimension":3,"text":"顺着家里的饭点把话聊够"}]},{"prompt":"旅途中有一段车程被取消了。","options":[{"dimension":3,"text":"找同行的人讨论都想保留什么"},{"dimension":2,"text":"马上把接下来几个点重新组合"},{"dimension":1,"text":"留在原地拍拍照再决定"},{"dimension":0,"text":"确定下一班和原有计划的衔接"}]},{"prompt":"打破忙乱的一周，最想给自己补什么？","options":[{"dimension":0,"text":"三天按时吃饭"},{"dimension":3,"text":"一顿讲完心事的长晚饭"},{"dimension":2,"text":"两小时不被打断的工作"},{"dimension":1,"text":"一场一直睡到自然醒的晨觉"}]},{"prompt":"刚到家、还没换衣服，你通常想先干吗？","options":[{"dimension":2,"text":"把还在想的那件事接着做完"},{"dimension":3,"text":"跟家人或朋友报一声到家"},{"dimension":0,"text":"把钥匙放回老地方，把衣服挂好"},{"dimension":1,"text":"坐下，听一会儿没有任务的声音"}]},{"prompt":"理想的周五晚上长什么样？","options":[{"dimension":3,"text":"临时叫熟人出门碰面"},{"dimension":0,"text":"早点收拾好就照常休息"},{"dimension":1,"text":"不知道会做什么，想起来再去做"},{"dimension":2,"text":"跟进一件盼了整周的事"}]},{"prompt":"你晚上常常忘记看表，通常是因为什么？","options":[{"dimension":0,"text":"顺着一直做的流程自然而然到了睡前"},{"dimension":1,"text":"窝着听雨太舒服"},{"dimension":2,"text":"正做得顺手停不下来"},{"dimension":3,"text":"这一轮话题刚好聊到深处"}]},{"prompt":"周末醒来有一间空房间等你，你会先做什么？","options":[{"dimension":1,"text":"带一本书进去慢慢翻"},{"dimension":2,"text":"搬进没做完的东西专心弄一下午"},{"dimension":3,"text":"让朋友也来这里分一块地方"},{"dimension":0,"text":"开窗通风，把桌子收好"}]},{"prompt":"有人送你一张晚上九点开演的票。","options":[{"dimension":3,"text":"看跟谁一起去再决定"},{"dimension":2,"text":"很喜欢就把当天活提前做完"},{"dimension":1,"text":"到傍晚有精神再考虑"},{"dimension":0,"text":"先确认回家时间能不能接受"}]},{"prompt":"临睡前总有一件事让你想再等一会儿，那会是什么？","options":[{"dimension":0,"text":"把习惯的收尾做完"},{"dimension":3,"text":"等聊天对面把故事说完"},{"dimension":2,"text":"刚想到一个好点子要写下来"},{"dimension":1,"text":"再享受一点谁也不叫我的时间"}]},{"prompt":"你会把哪种时刻记成「今天过得不错」？","options":[{"dimension":1,"text":"留给自己的那一段足够长"},{"dimension":0,"text":"按时把平常的小事都做了"},{"dimension":3,"text":"和想念的人聊到了想聊的事"},{"dimension":2,"text":"把挺难的东西推进一大截"}]},{"prompt":"今晚打算做顿吃的，心里最想留下什么？","options":[{"dimension":2,"text":"短时间做成一桌菜的痛快"},{"dimension":1,"text":"洗洗切切慢下来的感觉"},{"dimension":0,"text":"一份下回还做得出来的简单做法"},{"dimension":3,"text":"饭桌上有人愿意添一碗"}]},{"prompt":"一周只能固定一件想保留的好事，你挑？","options":[{"dimension":0,"text":"同一个时间做一件小事"},{"dimension":1,"text":"一晚把所有安排拒之门外"},{"dimension":2,"text":"一块完整的时间做喜欢的事"},{"dimension":3,"text":"一顿长期约得上的饭"}]},{"prompt":"行程一片空白时，你觉得哪件事最先值得标上？","options":[{"dimension":1,"text":"什么也不标，给未知留着"},{"dimension":2,"text":"任务最难啃的那一块"},{"dimension":3,"text":"某个人终于也有空的下午"},{"dimension":0,"text":"起床与睡觉两个时间"}]},{"prompt":"按一个月算，你最想减少哪种消耗？","options":[{"dimension":2,"text":"刚进入状态就被打断"},{"dimension":3,"text":"和很多人说话却没聊深一句"},{"dimension":0,"text":"每次都重新决定生活细节"},{"dimension":1,"text":"一个缝隙接着一个待办"}]},{"prompt":"假如家门口有个免费共享房间，你会怎么使用？","options":[{"dimension":3,"text":"组织三四个熟人定期聚"},{"dimension":0,"text":"定期去练习一项习惯"},{"dimension":1,"text":"路过时进去发会儿呆"},{"dimension":2,"text":"预约整档时间做个人项目"}]},{"prompt":"你最愿意长期坚持的一件运动是？","options":[{"dimension":1,"text":"想走就出门，不记录"},{"dimension":0,"text":"每晚一圈差不多的步数"},{"dimension":3,"text":"和朋友约好才能越走越起劲"},{"dimension":2,"text":"有目标的一段集中训练"}]},{"prompt":"选一个一周都有效的小奖励。","options":[{"dimension":2,"text":"做完那一块后的庆功饮料"},{"dimension":1,"text":"一直没用掉的一张空白券"},{"dimension":0,"text":"每天结束时打一颗小勾"},{"dimension":3,"text":"约到了三次才碰头的一声笑"}]},{"prompt":"到了需要暂时放下工作的假期，你希望第一个早晨怎样开始？","options":[{"dimension":3,"text":"一个人睡醒后有人等我吃饭"},{"dimension":2,"text":"突然有劲，去做平时没空做的事"},{"dimension":1,"text":"没有闹钟，醒了还能眯一会"},{"dimension":0,"text":"照习惯醒来，慢慢做早餐"}]},{"prompt":"哪句话最像你嘴里那句「日子舒服了」？","options":[{"dimension":0,"text":"想睡时睡得着，醒来知道先做什么"},{"dimension":3,"text":"回想起来今天见到了想见的人"},{"dimension":2,"text":"心里那件事终于专注地做够了"},{"dimension":1,"text":"路上等等风，手上没催人的单"}]}],"art":"data:image/jpeg;base64,"};
